<div class="admin-page-title"><div><span class="eyebrow">VENDAS ONLINE</span><h1>Pedidos de compra</h1><p>Acompanhe os pedidos registrados pelo catálogo.</p></div></div><div class="admin-card"><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Itens</th><th>Total</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($compras as $c): ?><tr><td>#<?= (int)$c['id'] ?></td><td><?= h($c['nome']) ?><small class="table-sub"><?= h($c['email']) ?></small></td><td><?= date('d/m/Y H:i',strtotime($c['data_compra'])) ?></td><td><?= (int)$c['itens'] ?></td><td><?= money($c['total']) ?></td><td><span class="status <?= h($c['status']) ?>"><?= h(status_label($c['status'])) ?></span></td><td><?php if($c['status']!=='cancelado'): ?><form method="post" action="<?= h(url('admin/controllers/acao.php')) ?>" class="inline-actions"><?= csrf_field() ?><input type="hidden" name="acao" value="update_purchase"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><select name="status"><option value="confirmado" <?= $c['status']==='confirmado'?'selected':'' ?>>Confirmado</option><option value="separando" <?= $c['status']==='separando'?'selected':'' ?>>Separando</option><option value="concluido" <?= $c['status']==='concluido'?'selected':'' ?>>Concluído</option><option value="cancelado" <?= $c['status']==='cancelado'?'selected':'' ?>>Cancelado</option></select><button class="link-button">Salvar</button></form><form method="post" action="<?= h(url('admin/controllers/acao.php')) ?>" onsubmit="return confirm('Cancelar pedido e devolver os itens ao estoque?')"><?= csrf_field() ?><input type="hidden" name="acao" value="delete_purchase"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="link-button danger-text">Cancelar pedido</button></form><?php else: ?><span class="muted">Pedido cancelado</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
